/** Unsigned key encoding does not make a negative dictionary reference a valid RDF term-owner component. */
class TermOwnerGraphVerifierUnsignedDomainTest {

	private static final String SPOC = TripleIndex.nativeDatabaseName("term-spoc", true);
	private static final String CSPO = TripleIndex.nativeDatabaseName("term-cspo", true);

	@TempDir
	Path directory;

	@ParameterizedTest
	@EnumSource(ReferenceRole.class)
	void rejectsNegativeReferencesInDirectCanonicalDecodeAndActualNativeGraph(ReferenceRole role) throws Exception {
		long[] quad = validQuad();
		quad[role.position] |= Long.MIN_VALUE;
		assertThat(quad[role.position]).isNegative();
		assertThat(ValueIds.isReference(quad[role.position])).isTrue();
		byte[] cspo = key("cspo", quad);
		seed(quad);
		Map<String, Map<String, String>> before = image(directory);
		assertAll("signed reference role " + role,
				() -> {
					ByteBuffer encoded = ByteBuffer.wrap(cspo);
					IOException failure = assertThrows(IOException.class,
							() -> TermOwnerGraphVerifier.cspoOwnerId(encoded));
					assertMalformed(failure, "CSPO", role);
					assertThat(encoded.position()).isZero();
				},
				() -> {
					IOException failure = assertThrows(IOException.class, () -> verifyGraph(directory));
					assertMalformed(failure, "SPOC", role);
				},
				() -> assertThat(image(directory)).isEqualTo(before));
	}

	@ParameterizedTest(name = "full unsigned inline alias = {0}")
	@ValueSource(booleans = { false, true })
	void preservesInlineCategoryWithoutTreatingItsSignAsAReferenceSign(boolean fullUnsignedAlias) throws Exception {
		var values = SimpleValueFactory.getInstance();
		var literal = values.createLiteral(-3.0d);
		long packed = Values.packLiteral(literal);
		assertThat(packed).as("the actual production encoder emits a nonnegative ID").isPositive();
		long object = fullUnsignedAlias ? packed | Long.MIN_VALUE : packed;
		assertThat(object < 0L).isEqualTo(fullUnsignedAlias);
		assertThat(ValueIds.isInlined(object)).isTrue();
		assertThat(ValueIds.isReference(object)).isFalse();
		assertThat(Values.unpackLiteral(object, values)).isEqualTo(literal);
		// The upper-half alias is accepted by the inline category/decoder, NOT emitted canonically by its writer.
		assertThat(Values.packLiteral(Values.unpackLiteral(object, values))).isEqualTo(packed);
		long[] quad = validQuad();
		quad[TripleIndex.OBJ_IDX] = object;
		seed(quad);
		Map<String, Map<String, String>> before = image(directory);
		assertAll("inline category control, full unsigned alias=" + fullUnsignedAlias,
				() -> assertThat(TermOwnerGraphVerifier.cspoOwnerId(ByteBuffer.wrap(key("cspo", quad))))
						.isEqualTo(quad[TripleIndex.CONTEXT_IDX]),
				() -> verifyGraph(directory),
				() -> assertThat(image(directory)).isEqualTo(before));
	}

	@Test
	void actualStartupRejectsNegativeCspoAllocationExtremumWithoutChangingAdmittedStore() throws Exception {
		LmdbCompatibilityFixtures.extract("v2-610-explicit-terms.zip", directory);
		LmdbStoreConfig config = new LmdbStoreConfig("spoc,posc").setTripleTermIndexes("spoc,cspo")
				.setInlineLiterals(false)
				.setAsyncValueCleanup(false)
				.setValueHashCacheEnabled(false)
				.setTripleDBSize(32L * 1024L * 1024L)
				.setValueDBSize(32L * 1024L * 1024L);
		LmdbStore pristine = new LmdbStore(directory.toFile(), config);
		try {
			pristine.init();
			try (var connection = pristine.getConnection()) {
				assertThat(connection.size()).isPositive();
			}
		} finally {
			pristine.shutDown();
		}
		// First admission legitimately installed the legacy fence. Rejection must not rewrite any existing authority.
		assertThat(LmdbPersistentAdjacencyFence.matches(directory)).isTrue();
		Path valuesDirectory = directory.resolve("values");
		Map<String, Map<String, String>> original = image(valuesDirectory);
		long[] quad = decodeCspo(lastCspo(valuesDirectory));
		assertThat(quad[TripleIndex.CONTEXT_IDX]).isPositive();
		assertThat(ValueIds.getIdType(quad[TripleIndex.CONTEXT_IDX])).isEqualTo(ValueIds.T_TRIPLE);
		quad[TripleIndex.CONTEXT_IDX] |= Long.MIN_VALUE;
		byte[] corruptCspo = key("cspo", quad);
		byte[] corruptSpoc = key("spoc", quad);
		assertThat(original.get(CSPO)).doesNotContainKey(hex(corruptCspo));
		assertThat(original.get(SPOC)).doesNotContainKey(hex(corruptSpoc));
		LmdbCompatibilityFixtures.nativePut(directory, CSPO, corruptCspo, new byte[0]);
		LmdbCompatibilityFixtures.nativePut(directory, SPOC, corruptSpoc, new byte[0]);
		Map<String, Map<String, String>> expected = new TreeMap<>(original);
		for (String order : List.of("spoc", "cspo")) {
			String database = order.equals("spoc") ? SPOC : CSPO;
			Map<String, String> rows = new TreeMap<>(original.get(database));
			rows.put(hex(key(order, quad)), "");
			expected.put(database, rows);
		}
		assertThat(image(valuesDirectory)).isEqualTo(expected);
		assertThat(lastCspo(valuesDirectory)).containsExactly(corruptCspo);
		Map<String, String> before = LmdbCompatibilityFixtures.snapshot(directory);
		for (int attempt = 0; attempt < 2; attempt++) {
			assertAll("actual allocation-extremum rejection " + attempt,
					() -> assertStartupRejectedAtActualExtremum(config, corruptCspo),
					() -> assertThat(LmdbCompatibilityFixtures.snapshot(directory)).isEqualTo(before),
					() -> assertThat(image(valuesDirectory)).isEqualTo(expected));
		}
	}

	private void assertStartupRejectedAtActualExtremum(LmdbStoreConfig config, byte[] corruptCspo) {
		List<String> observedKeys = new ArrayList<>();
		List<Boolean> allocatorCalls = new ArrayList<>();
		try (MockedStatic<TermOwnerGraphVerifier> calls = mockStatic(TermOwnerGraphVerifier.class, invocation -> {
			if (invocation.getMethod().getName().equals("cspoOwnerId")) {
				ByteBuffer encoded = ((ByteBuffer) invocation.getArgument(0)).duplicate();
				byte[] key = new byte[encoded.remaining()];
				encoded.get(key);
				observedKeys.add(hex(key));
				boolean allocation = StackWalker.getInstance()
						.walk(frames -> frames.anyMatch(frame -> frame.getClassName().equals(ValueStore.class.getName())
								&& frame.getMethodName().equals("initializeTermIndexes")));
				allocatorCalls.add(allocation);
			}
			return invocation.callRealMethod();
		})) {
			assertAll("real startup initializer and its exact input",
					() -> {
						LmdbStore store = new LmdbStore(directory.toFile(), config);
						try {
							SailException failure = assertThrows(SailException.class, store::init);
							assertThat(failure.getCause()).isInstanceOf(IOException.class)
									.hasMessage("Malformed canonical CSPO term owner key")
									.hasRootCauseMessage("invalid canonical term owner key");
						} finally {
							store.shutDown();
						}
					},
					() -> assertThat(observedKeys).containsExactly(hex(corruptCspo)),
					() -> assertThat(allocatorCalls).containsExactly(true));
		}
	}

	private static void assertMalformed(IOException failure, String order, ReferenceRole role) {
		assertThat(failure).hasMessage("Malformed canonical " + order + " term owner key")
				.hasRootCauseMessage(role == ReferenceRole.OWNER ? "invalid canonical term owner key"
						: "invalid RDF roles in canonical term owner");
	}

	private static long[] validQuad() {
		return new long[] { ValueIds.createId(ValueIds.T_URI, 10), ValueIds.createId(ValueIds.T_URI, 11),
				ValueIds.createId(ValueIds.T_URI, 12), ValueIds.createId(ValueIds.T_TRIPLE, 13) };
	}

	private void seed(long[] quad) throws IOException {
		withTerms(directory, true, (stack, txn, spoc, cspo) -> {
			put(stack, txn, spoc, key("spoc", quad));
			put(stack, txn, cspo, key("cspo", quad));
			return null;
		});
	}

	private static void verifyGraph(Path directory) throws IOException {
		withTerms(directory, false, (stack, txn, spoc, cspo) -> {
			TermOwnerGraphVerifier.verify(txn, spoc, cspo);
			return null;
		});
	}

	private static Map<String, Map<String, String>> image(Path directory) throws IOException {
		return withTerms(directory, false, (stack, txn, spoc, cspo) -> Map.of(
				SPOC, LmdbPersistentAdjacencyCompactionWorkTest.records(txn, spoc),
				CSPO, LmdbPersistentAdjacencyCompactionWorkTest.records(txn, cspo)));
	}

	private static byte[] lastCspo(Path directory) throws IOException {
		return withTerms(directory, false, (stack, txn, spoc, cspo) -> {
			PointerBuffer handle = stack.mallocPointer(1);
			E(mdb_cursor_open(txn, cspo, handle));
			long cursor = handle.get(0);
			try {
				MDBVal key = MDBVal.calloc(stack);
				MDBVal value = MDBVal.calloc(stack);
				E(mdb_cursor_get(cursor, key, value, MDB_LAST));
				byte[] encoded = new byte[(int) key.mv_size()];
				key.mv_data().duplicate().get(encoded);
				assertThat(value.mv_size()).isZero();
				return encoded;
			} finally {
				mdb_cursor_close(cursor);
			}
		});
	}

	private static long[] decodeCspo(byte[] encoded) {
		ByteBuffer key = ByteBuffer.wrap(encoded);
		long owner = Varint.readUnsigned(key);
		long[] quad = { Varint.readUnsigned(key), Varint.readUnsigned(key), Varint.readUnsigned(key), owner };
		assertThat(key.hasRemaining()).isFalse();
		return quad;
	}

	/** Negative inputs use literal canonical uint64 bytes independently of the newly extended writer. */
	private static byte[] key(String order, long[] quad) {
		ByteBuffer encoded = ByteBuffer.allocate(36);
		for (char field : order.toCharArray()) {
			long id = quad["spoc".indexOf(field)];
			if (id < 0L) {
				encoded.put((byte) 0xff).putLong(id);
			} else {
				Varint.writeUnsigned(encoded, id);
			}
		}
		return Arrays.copyOf(encoded.array(), encoded.position());
	}

	private static String hex(byte[] bytes) {
		return HexFormat.of().formatHex(bytes);
	}

	private static void put(MemoryStack stack, long txn, int database, byte[] key) throws IOException {
		E(mdb_put(txn, database, MDBVal.calloc(stack).mv_data(stack.bytes(key)),
				MDBVal.calloc(stack).mv_data(stack.bytes(new byte[0])), 0));
	}

	private static <T> T withTerms(Path directory, boolean write, TermAction<T> action) throws IOException {
		long env = 0L;
		try (MemoryStack stack = MemoryStack.stackPush()) {
			PointerBuffer handle = stack.mallocPointer(1);
			E(mdb_env_create(handle));
			env = handle.get(0);
			E(mdb_env_set_maxdbs(env, 49));
			if (write) {
				E(mdb_env_set_mapsize(env, 16L * 1024L * 1024L));
			}
			E(mdb_env_open(env, directory.toString(), MDB_NOTLS | (write ? 0 : MDB_RDONLY), 0664));
			LmdbUtil.Transaction<T> transaction = (lookup, txn) -> {
				int spoc = LmdbUtil.openDatabaseWithTxn(txn, SPOC, write ? MDB_CREATE : 0);
				int cspo = LmdbUtil.openDatabaseWithTxn(txn, CSPO, write ? MDB_CREATE : 0);
				return action.run(lookup, txn, spoc, cspo);
			};
			return write ? LmdbUtil.writeTransaction(env, transaction) : LmdbUtil.readTransaction(env, transaction);
		} finally {
			if (env != 0L) {
				mdb_env_close(env);
			}
		}
	}

	@FunctionalInterface
	private interface TermAction<T> {
		T run(MemoryStack stack, long txn, int spoc, int cspo) throws IOException;
	}

	enum ReferenceRole {
		OWNER(TripleIndex.CONTEXT_IDX),
		SUBJECT(TripleIndex.SUBJ_IDX),
		PREDICATE(TripleIndex.PRED_IDX),
		OBJECT(TripleIndex.OBJ_IDX);

		final int position;

		ReferenceRole(int position) {
			this.position = position;
		}
	}
}
